class NextUnfoldHover{static instances=[];constructor(element){this.element=element;this.textElements=element.querySelectorAll(".dan-unfold-hover__text");this.splitTexts=[];this.initialize()}
initialize(){if(!this.textElements.length)return;this.createSplitTexts()}
createSplitTexts(){this.textElements.forEach(textElement=>{const content=textElement.getAttribute('data-content');if(!content)return;textElement.innerHTML=content;const splitText=new SplitText(textElement,{type:"chars, words",charsClass:"char",wordsClass:"word"});splitText.chars.forEach((char,index)=>{char.style.setProperty("--char-index",index)});this.splitTexts.push({element:textElement,split:splitText,originalContent:content})})}
destroy(){this.splitTexts.forEach(({element,split,originalContent})=>{split.revert();element.innerHTML=originalContent});this.splitTexts=[]}
static destroyAll(){NextUnfoldHover.instances.forEach(instance=>instance.destroy());NextUnfoldHover.instances=[]}}
const dancepad_unfold_hover=()=>{NextUnfoldHover.destroyAll();document.querySelectorAll(".dan-unfold-hover").forEach(element=>{element.removeAttribute('data-flickering');NextUnfoldHover.instances.push(new NextUnfoldHover(element))})}